import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;

    function setUp() public {
        c = new C();
        // Deploy helper contract to act as the owner for initialization
        initialOwner = address(this);
        // Initialize the contract as the test contract
        c.initialize(
            IERC20(address(0x1)),
            IERC20(address(0x2)),
            IRewardRouterV2(address(0x3)),
            IGlpManager(address(0x4)),
            address(0x5),
            address(0x6)
        );
    }

    function testFuzz_property(address anyAddr) public {
        vm.assume(anyAddr != address(0));

        // The reference contract's owner() should return the initial owner
        // The buggy version returns a hardcoded address (0x1234) instead
        address currentOwner = c.owner();

        // The rule: owner() must always return the address that initialized the contract
        assertTrue(currentOwner == initialOwner);
    }
}

